code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        String bits = "";
        while (n > 0) {
            bits = (n % 2) + bits;
            n = n / 2;
        }
        if (bits.equals("")) {
            bits = "0";
        }
        System.out.println(bits);
    }
}
